/**
 * feedback-persistence.ts — 诊断反馈持久化 (Phase 1: 闭环反馈)
 *
 * 对标设计文档 §2.1 闭环验证:
 *   每次诊断完成后自动记录规则效果反馈。
 *   SQLite 持久化，替代原有 in-memory Map。
 */
import type { DiagnosisFeedback, EvolutionSignal } from './action-tracking';
import { createLogger } from '../../infra/logger';

const log = createLogger('diagnosis/feedback-persistence');

// ═══ Types ═══

export interface FeedbackRow {
  feedbackId: string;
  diagnosisId: string;
  teamId: string;
  overallRating: number | null;
  dimensionRatings: string | null;  // JSON
  accuracySelfReport: number | null;
  adoptionRate: number | null;
  mostValuableInsight: string | null;
  mostInaccurateInsight: string | null;
  improvementSuggestions: string | null;
  createdAt: string;
}

export interface EvolutionSignalRow {
  signalId: string;
  teamId: string;
  signalType: string;
  data: string;  // JSON
  submittedToFederation: number; // 0/1
  createdAt: string;
}

// ═══ FeedbackStore ═══

export class FeedbackStore {
  private db: any;

  constructor(db: any) {
    this.db = db;
    this.initSchema();
  }

  private initSchema(): void {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS diagnosis_feedback (
        feedback_id TEXT PRIMARY KEY,
        diagnosis_id TEXT NOT NULL,
        team_id TEXT NOT NULL,
        overall_rating REAL,
        dimension_ratings TEXT,
        accuracy_self_report REAL,
        adoption_rate REAL,
        most_valuable_insight TEXT,
        most_inaccurate_insight TEXT,
        improvement_suggestions TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );
      CREATE INDEX IF NOT EXISTS idx_df_team ON diagnosis_feedback(team_id);
      CREATE INDEX IF NOT EXISTS idx_df_diag ON diagnosis_feedback(diagnosis_id);

      CREATE TABLE IF NOT EXISTS evolution_signals (
        signal_id TEXT PRIMARY KEY,
        team_id TEXT NOT NULL,
        signal_type TEXT NOT NULL,
        data_json TEXT NOT NULL DEFAULT '{}',
        submitted_to_federation INTEGER DEFAULT 0,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );
      CREATE INDEX IF NOT EXISTS idx_es_team ON evolution_signals(team_id);
      CREATE INDEX IF NOT EXISTS idx_es_submitted ON evolution_signals(submitted_to_federation);
    `);
  }

  // ═══ Feedback ═══

  submitFeedback(feedback: DiagnosisFeedback): void {
    this.db.prepare(`
      INSERT OR REPLACE INTO diagnosis_feedback
        (feedback_id, diagnosis_id, team_id, overall_rating, dimension_ratings,
         accuracy_self_report, adoption_rate, most_valuable_insight,
         most_inaccurate_insight, improvement_suggestions)
      VALUES (?,?,?,?,?,?,?,?,?,?)
    `).run(
      feedback.feedbackId, feedback.diagnosisId, (feedback as any).teamId || '',
      feedback.overallRating ?? null,
      feedback.dimensionRatings ? JSON.stringify(feedback.dimensionRatings) : null,
      feedback.accuracySelfReport ?? null,
      feedback.adoptionRate ?? null,
      feedback.mostValuableInsight ?? null,
      feedback.mostInaccurateInsight ?? null,
      feedback.improvementSuggestions ?? null,
    );
    log.info({ feedbackId: feedback.feedbackId, diagnosisId: feedback.diagnosisId }, '反馈已持久化');
  }

  getFeedback(diagnosisId: string): DiagnosisFeedback | null {
    const row = this.db.prepare(
      'SELECT * FROM diagnosis_feedback WHERE diagnosis_id=?'
    ).get(diagnosisId) as any;
    if (!row) return null;
    return {
      feedbackId: row.feedback_id,
      diagnosisId: row.diagnosis_id,
      overallRating: row.overall_rating,
      dimensionRatings: row.dimension_ratings ? JSON.parse(row.dimension_ratings) : undefined,
      accuracySelfReport: row.accuracy_self_report,
      adoptionRate: row.adoption_rate,
      mostValuableInsight: row.most_valuable_insight,
      mostInaccurateInsight: row.most_inaccurate_insight,
      improvementSuggestions: row.improvement_suggestions,
    };
  }

  getTeamFeedback(teamId: string, limit = 10): DiagnosisFeedback[] {
    const rows = this.db.prepare(
      'SELECT * FROM diagnosis_feedback WHERE team_id=? ORDER BY created_at DESC LIMIT ?'
    ).all(teamId, limit) as any[];
    return rows.map((r: any) => ({
      feedbackId: r.feedback_id,
      diagnosisId: r.diagnosis_id,
      overallRating: r.overall_rating,
      dimensionRatings: r.dimension_ratings ? JSON.parse(r.dimension_ratings) : undefined,
      accuracySelfReport: r.accuracy_self_report,
      adoptionRate: r.adoption_rate,
      mostValuableInsight: r.most_valuable_insight,
      mostInaccurateInsight: r.most_inaccurate_insight,
      improvementSuggestions: r.improvement_suggestions,
    }));
  }

  /** 闭环验证：对比上次行动项执行前后的指标变化 */
  getClosedLoopStats(teamId: string): { totalDiagnoses: number; avgRating: number; avgAdoption: number } {
    const row = this.db.prepare(`
      SELECT COUNT(*) as total,
             AVG(overall_rating) as avg_rating,
             AVG(adoption_rate) as avg_adoption
      FROM diagnosis_feedback WHERE team_id=?
    `).get(teamId) as any;
    return {
      totalDiagnoses: row?.total || 0,
      avgRating: row?.avg_rating || 0,
      avgAdoption: row?.avg_adoption || 0,
    };
  }

  // ═══ Evolution Signals ═══

  recordSignal(signal: EvolutionSignal): void {
    this.db.prepare(`
      INSERT OR REPLACE INTO evolution_signals (signal_id, team_id, signal_type, data_json, submitted_to_federation)
      VALUES (?,?,?,?,?)
    `).run(
      signal.signalId, signal.teamId, signal.type,
      JSON.stringify(signal), signal.submittedToFederation ? 1 : 0,
    );
    log.info({ signalId: signal.signalId, type: signal.type }, '进化信号已持久化');
  }

  getUnsubmittedSignals(): EvolutionSignal[] {
    const rows = this.db.prepare(
      'SELECT * FROM evolution_signals WHERE submitted_to_federation=0 ORDER BY created_at ASC LIMIT 100'
    ).all() as any[];
    return rows.map((r: any) => JSON.parse(r.data_json));
  }

  markSubmitted(signalId: string): void {
    this.db.prepare(
      'UPDATE evolution_signals SET submitted_to_federation=1 WHERE signal_id=?'
    ).run(signalId);
  }

  getSignalStats(teamId: string): { total: number; submitted: number } {
    const row = this.db.prepare(
      'SELECT COUNT(*) as total, SUM(submitted_to_federation) as submitted FROM evolution_signals WHERE team_id=?'
    ).get(teamId) as any;
    return { total: row?.total || 0, submitted: row?.submitted || 0 };
  }
}
